import { flags } from './flags'

const root = document.querySelector<HTMLElement>('#app')

if (root) {
  root.textContent = `${String(flags.checkoutV2)}:${String(flags.theme)}`
}

examples/consumer/vite.config.ts.text:
import { fileURLToPath } from 'node:url'

import { featureFlags } from '@frontend-architect-eval/feature-flags'
import { defineConfig } from 'vite'

const root = fileURLToPath(new URL('.', import.meta.url))

export default defineConfig({
  root,
  plugins: [
    featureFlags({
      source: new URL('./flags.json', import.meta.url),
      expose: ['checkoutV2', 'theme'],
    }),
  ],
  build: {
    outDir: 'dist',
    emptyOutDir: true,
    sourcemap: true,
  },
})

